        // Contractor_placement.php L504-575 → bestMatch
        app.MapGet("/api/v1/contractor/bestmatch", async (string custids, string contractorname, string tsweek, SqlConnection dbConnection) =>
        {
            var list = new List<dynamic>();
            var custidsArray = QuoteAndTransform(custids);
            var contractorsArray = QuoteAndTransform(await Contractor.BestMatchAsync(contractorname));

            if (custidsArray.Count < 1 || contractorsArray.Count < 1)
            {
                return Results.Json(list);
            }

            var query = @"SELECT cp.id AS id, cp.start_date AS start_date, cp.deactivation_date AS deactivation_date, 
                           cp.is_active AS is_active, c.id AS contractor_id, c.firstname AS firstname, 
                           c.mi AS mi, c.lastname AS lastname, c.is_active AS is_active_contractor 
                      FROM contractor_placement cp, contractor c 
                      WHERE cp.contractor_id = c.id 
                      AND cp.customer_id IN (@CustIds) 
                      AND c.id IN (@Contractors)";
            list = (await dbConnection.QueryAsync<dynamic>(query, new { CustIds = custidsArray, Contractors = contractorsArray })).ToList();

            if (list.Count < 1)
            {
                query = @"SELECT cp.id AS id, cp.start_date AS start_date, cp.deactivation_date AS deactivation_date, 
                          cp.is_active AS is_active, c.id AS contractor_id, c.firstname AS firstname, 
                          c.mi AS mi, c.lastname AS lastname, c.is_active AS is_active_contractor 
                     FROM contractor_placement cp, contractor c 
                     WHERE cp.contractor_id = c.id 
                     AND c.id IN (@Contractors)";
                list = (await dbConnection.QueryAsync<dynamic>(query, new { Contractors = contractorsArray })).ToList();
            }

            if (list.Count > 1)
            {
                var tssecs = DateTimeOffset.Parse(tsweek).ToUnixTimeSeconds();
                var maxdeviation = 7 * 86400;
                list = list.Aggregate(new List<dynamic>(), (carry, entry) =>
                {
                    if (ContractorPlacement.IsPerm(entry.id))
                    {
                        return carry;
                    }
                    else if (tssecs - DateTimeOffset.Parse(entry.start_date).ToUnixTimeSeconds() < -1 * maxdeviation)
                    {
                        return carry;
                    }
                    else if (entry.deactivation_date != "2000-01-01 00:00:00" &&
                             tssecs - DateTimeOffset.Parse(entry.deactivation_date).ToUnixTimeSeconds() > maxdeviation)
                    {
                        return carry;
                    }
                    else
                    {
                        carry.Add(entry);
                    }
                    return carry;
                });
            }

            return Results.Json(list);
        });

