        // Contractor_placement.php L337-389 → adjustPlacementStartDate
        app.MapPut("/api/v1/contractor/placement/{placement_id:int}", async (int placement_id, [FromQuery] string start_date, ContractorPlacementRepository repo) =>
        {
            // Model/Contractor_placement.php L340-341 → validate inputs
            if (placement_id == 0 || start_date == "2001-01-01")
            {
                return Results.BadRequest(new { error = "Invalid placement_id or start_date" });
            }

            // Model/Contractor_placement.php L344 → load placement
            var plcObj = await repo.GetPlacementByIdAsync(placement_id);
            if (plcObj == null || !plcObj.IsPopulated())
            {
                return Results.NotFound(new { error = "Placement not found" });
            }

            // Model/Contractor_placement.php L347-349 → update start date
            plcObj.StartDate = start_date;
            if (plcObj.HasChanged())
            {
                await repo.SaveAsync(plcObj);

                // Model/Contractor_placement.php L351 → delete invalid entries
                await ContractorPlacementOverdueStatusMap.DeleteInvalidEntriesAsync(plcObj.Id);

                // Model/Contractor_placement.php L352-369 → update profiles
                foreach (var profile in plcObj.AllProfiles())
                {
                    if (profile.ValidFrom <= profile.ValidTo)
                    {
                        plcObj.StartDate = DateSanitize(plcObj.StartDate);
                        if (plcObj.StartDate < profile.ValidFrom)
                        {
                            profile.ValidFrom = plcObj.StartDate;
                            await profile.SaveAsync();
                            await Profile.VoidAfterProfileAsync(plcObj.Id, profile.ValidFrom);
                            break;
                        }
                        if (plcObj.StartDate >= profile.ValidFrom && plcObj.StartDate <= profile.ValidTo)
                        {
                            profile.ValidFrom = plcObj.StartDate;
                            await profile.SaveAsync();
                            await Profile.VoidAfterProfileAsync(plcObj.Id, profile.ValidFrom);
                            break;
                        }
                        await profile.AdjustBurdenNewAsync(plcObj.IsPassthru);
                        await profile.SaveAsync();
                    }
                }

                // Model/Contractor_placement.php L373-385 → H1B Employees Credit Exception
                var visaTypes = TrimAll(GetConfig("100 percentage credit work authorization list", "H1B,CPT,OPT EAD,TN", "App"), true, ',', false);
                var demographicId = await ContractorPlacement.CheckDemographicReverseMapAsync(placement_id);
                var demographicObj = await OnbDemographic.GetByIdAsync(demographicId);
                var visaType = demographicObj.GetVisaType();
                var cutoffDate = DateToDate(GetConfig("100 percentage credit cutoff date", "2023-10-06", "App"));

                if (visaTypes.Contains(visaType))
                {
                    foreach (var profile in plcObj.AllProfiles())
                    {
                        if (profile.ValidFrom >= cutoffDate)
                        {
                            await Profile.UpdateH1bEmployeesApplyPctAsync(profile.Id);
                        }
                    }
                }
            }

            return Results.Ok(new { message = "Placement start date adjusted successfully" });
        });

