        app.MapGet("/api/v1/contractor-placement/{contractor_placement_id}/match-candidate", async (int contractorPlacementId, [FromQuery] int jobreqId, IDbConnection dbConnection) =>
        {
            var cp = new ContractorPlacement(contractorPlacementId, dbConnection);
            if (!cp.IsPopulated())
            {
                return Results.NotFound("Placement not populated");
            }

            var contractor = new Contractor(cp.ContractorId, dbConnection);
            if (!contractor.IsPopulated() || contractor.Id < 2)
            {
                return Results.NotFound("Contractor not populated");
            }

            if (jobreqId < 2)
            {
                jobreqId = cp.JobreqId;
            }
            if (jobreqId < 2)
            {
                return Results.NotFound("Job not populated");
            }

            var candidates = await dbConnection.QueryAsync<int>("SELECT DISTINCT candidate_id FROM candidate_activity WHERE jobreq_id = @JobreqId", new { JobreqId = jobreqId });
            foreach (var candidateId in candidates)
            {
                var candidate = new Candidate(candidateId, dbConnection);
                if (candidate.Email == contractor.Email)
                {
                    return Results.Json(candidate);
                }
            }

            foreach (var candidateId in candidates)
            {
                var candidate = new Candidate(candidateId, dbConnection);
                if (contractor.Firstname == candidate.Firstname && contractor.Lastname == candidate.Lastname)
                {
                    return Results.Json(candidate);
                }
            }

            return Results.NotFound();
        });

