        app.MapPut("/api/v1/job/change", async (int old_id, int new_id, ContractorPlacementDbContext db) =>
        {
            if (old_id == 0 || new_id == 0)
            {
                return Results.BadRequest("Invalid job IDs.");
            }

            var updated = 0;
            var activePlacements = await db.ContractorPlacements
                .Where(p => p.JobreqId == old_id && p.IsActive == "Y")
                .ToListAsync();

            foreach (var plc in activePlacements)
            {
                plc.JobreqId = new_id;
                db.ContractorPlacements.Update(plc);
                updated++;
            }

            await db.SaveChangesAsync();
            return Results.Ok(new { updated });
        });

        return app;
    }

