    private static IEnumerable<string> TrimAll(string input, bool trim, char separator, bool removeEmpty)
    {
        var parts = input.Split(separator);
        foreach (var part in parts)
        {
            var trimmed = trim ? part.Trim() : part;
            if (!removeEmpty || !string.IsNullOrWhiteSpace(trimmed))
                yield return trimmed;
        }
    }

